// ========================================
// TEMPORARY: Helper function for test greeting selection
// ========================================
// Use this function instead of accessing cachedPromptAudio directly when testing ask_name
// Returns test candidate audio if TEST_GREETING_CANDIDATE is set and key is 'ask_name'
// Otherwise returns production audio
export function getCachedPromptAudio(key: keyof typeof cachedPromptAudio): string {
  if (key === 'ask_name' && testCandidateAudio) {
    return testCandidateAudio;
  }
  return cachedPromptAudio[key];
}